if (this._cache) return this._cache;

try {
    const json = window.localStorage.getItem(this.STORAGE_KEY);
    this._cache = json ? JSON.parse(json) : {};
} catch (e) {
    console.error("[UserPreferenceService] Parse error", e);
    this._cache = {};
}

return this._cache;

try {
    window.localStorage.setItem(this.STORAGE_KEY, JSON.stringify(this._cache));
} catch (e) {
    console.error("[UserPreferenceService] Save error", e);
}

const allPrefs = this._load();

// Check if category exists, then check if key exists
if (allPrefs[category] && allPrefs[category][key] !== undefined) {
    return allPrefs[category][key];
}

return defaultValue;

this._load(); // Ensure cache is warm

// Initialize category namespace if it doesn't exist
if (!this._cache[category]) {
    this._cache[category] = {};
}

this._cache[category][key] = value;
this._persist();

this._load();
if (this._cache[category] && this._cache[category][key]) {
    delete this._cache[category][key];
    this._persist();
}
